import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float, mix } from 'three/tsl';
import { gsap } from 'gsap';
import { fontAtlasText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-quote-panel';
  group.position.set(1.25, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 2.4;
  const height = 1.5;

  const geometry = new THREE.PlaneGeometry(width, height);
  const map = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const tex = texture(map);
  const inkTint = vec4(0x16 / 255, 0x16 / 255, 0x1d / 255, 1.0);
  const colorNode = mix(tex, inkTint, float(0.06));

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = colorNode;
  material.transparent = true;

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Accent edge frame (thin plane behind, slightly larger, accent color)
  const edgeGeometry = new THREE.PlaneGeometry(width + 0.04, height + 0.04);
  const edgeMaterial = new THREE.MeshBasicNodeMaterial();
  edgeMaterial.colorNode = vec4(0xff / 255, 0x2a / 255, 0x38 / 255, 1.0);
  edgeMaterial.transparent = true;
  edgeMaterial.opacity = 0.0;
  const edgeMesh = new THREE.Mesh(edgeGeometry, edgeMaterial);
  edgeMesh.position.z = -0.01;
  group.add(edgeMesh);

  // Quote text (client quote) - Lora serif style via font atlas
  const quoteText = fontAtlasText(ctx.fontAtlas, {
    text: '"An instrument, not an accessory."',
    font: 'display',
    weight: 400,
    size: 0.13,
    color: '#e8ecf2',
    maxWidth: width - 0.5,
    align: 'left',
  });
  quoteText.position.set(-width / 2 + 0.25, 0.35, 0.01);
  group.add(quoteText);

  // Attribution line - JetBrains Mono
  const attributionText = fontAtlasText(ctx.fontAtlas, {
    text: '— M. Halvorsen, Collector',
    font: 'text',
    weight: 700,
    size: 0.09,
    color: '#ff2a38',
    maxWidth: width - 0.5,
    align: 'left',
  });
  attributionText.position.set(-width / 2 + 0.25, -0.35, 0.01);
  group.add(attributionText);

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(group, primitive.params || {});
      }
    });
  }

  // Interaction state
  const baseY = group.position.y;
  let hoverTween = null;
  let pressTween = null;

  const onHoverIn = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    gsap.to(edgeMaterial, { opacity: 0.6, duration: 0.3, ease: 'power2.out' });
  };

  const onHoverOut = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
    gsap.to(edgeMaterial, { opacity: 0.0, duration: 0.3, ease: 'power2.out' });
  };

  const onClick = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out' });

    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-pricing.select', { nodeId: group.name });
    }
  };

  group.userData.handlers = {
    onPointerOver: onHoverIn,
    onPointerOut: onHoverOut,
    onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeMaterial);

    geometry.dispose();
    material.dispose();
    edgeGeometry.dispose();
    edgeMaterial.dispose();
    if (map) map.dispose();

    if (quoteText.userData && typeof quoteText.userData.dispose === 'function') {
      quoteText.userData.dispose();
    }
    if (attributionText.userData && typeof attributionText.userData.dispose === 'function') {
      attributionText.userData.dispose();
    }
  };

  return group;
}
